/* 止まーれー: the real call recorded at the paddock (from the user's own video) */
const TOMARE_SRC='data:audio/mpeg;base64,';
const PADAMB_SRC='data:audio/mpeg;base64,';
let TOMARE_BUF=null,TOMARE_EL=null;
function tomareLoad(){if(TOMARE_BUF||!AUD.ac)return;try{const bin=atob(TOMARE_SRC.split(',')[1]),u=new Uint8Array(bin.length);for(let i=0;i<bin.length;i++)u[i]=bin.charCodeAt(i);
  AUD.ac.decodeAudioData(u.buffer,b=>{TOMARE_BUF=b;},()=>{});}catch(e){}}
function tomareVoice(onfail){try{ensureAC();tomareLoad();
  if(TOMARE_BUF&&AUD.ac){const s=AUD.ac.createBufferSource();s.buffer=TOMARE_BUF;const g=AUD.ac.createGain();g.gain.value=PAMB.gain;s.connect(g);g.connect(AUD.fx||AUD.ac.destination);const t=AUD.ac.currentTime;s.start(t);padAmbDuck(t,TOMARE_BUF.duration);return true;}
  if(!TOMARE_EL)TOMARE_EL=new Audio(TOMARE_SRC);TOMARE_EL.currentTime=0;TOMARE_EL.volume=Math.min(1,AUD.vol+.2);const p=TOMARE_EL.play();if(p&&p.catch)p.catch(()=>{onfail&&onfail('音声を再生できませんでした');});return true;}
  catch(e){onfail&&onfail('音声を再生できませんでした');return false;}}
/* footsteps/snorts after the call */
SE.tomare=function(t){for(let i=0;i<7;i++)fxNoise(t+3.1+i*.17+Math.random()*.1,.05,900+Math.random()*500,2.5,.18);
  fxNoise(t+3.4,.35,500,.8,.4);fxNoise(t+3.9,.3,450,.8,.3);fxNoise(t+3,1.8,700,.3,.12,'lowpass');};
document.addEventListener('pointerdown',()=>{try{ensureAC();tomareLoad();}catch(e){}},{once:true});
ACT.voiceTest=()=>{const m=$('#vtmsg');if(m)m.textContent='再生中…';tomareVoice(msg=>{if(m)m.textContent=msg;se('whistle');});};
function fillVoiceSel(){const s=$('#vsel');if(s)s.remove();}

/* the next morning's sports paper lands on your phone after a graded-race win */
MAILS.paperWin={w:()=>0,mk:d=>({from:'press',fromName:'ターフスポ 電子版',subj:`【${d.race}】${d.name}V!!`,
  body:`${d.race}は${d.pop}番人気の${d.name}が${d.margin?d.margin+'差で':''}快勝。${d.j}騎手は「${pick(['馬の力を信じて乗りました','最後までよく頑張ってくれた','この馬ならやれると思っていました'])}」と笑顔。\n\nオーナーの${ownerName()}氏は口取り式で「${pick(['まだ夢の途中です','この馬と、有馬記念へ','厩舎のみんなのおかげです'])}」と声を詰まらせた。\n\n${d.pop>=5?'大波乱の決着に、場内はどよめきに包まれた。':'人気に応える完勝で、次走にも注目が集まる。'}`})};
showResult=(o=>function(){const RC=UI.race;const r=o.apply(this,arguments);try{const m=RC.order.find(f=>f.mine);if(m&&m.pos===1&&RC.race.g&&!RC.paperQ){RC.paperQ=1;const ph=PH();(ph.pend=ph.pend||[]).push({type:'paperWin',d:{race:RC.race.name,name:m.name,pop:m.pop,j:m.jname,margin:RC.order[1].margin}});}}catch(e){}return r;})(showResult);

/* paddock murmur: the same crowd recorded around the call, looped from the moment you walk into the paddock,
   ducked under the call (which carries its own murmur) so nothing suddenly starts */
const PAMB={buf:null,on:false,g:null,timer:null,gain:2.2,next:0};
function padAmbLoad(cb){if(PAMB.buf){cb&&cb();return;}try{const bin=atob(PADAMB_SRC.split(',')[1]),u=new Uint8Array(bin.length);for(let i=0;i<bin.length;i++)u[i]=bin.charCodeAt(i);AUD.ac.decodeAudioData(u.buffer,b=>{PAMB.buf=b;cb&&cb();},()=>{});}catch(e){}}
function padAmbStart(){if(PAMB.on||!AUD.se)return;if(!ensureAC())return;tomareLoad();PAMB.on=true;
  padAmbLoad(()=>{if(!PAMB.on)return;const ac=AUD.ac;PAMB.g=ac.createGain();PAMB.g.gain.setValueAtTime(0,ac.currentTime);PAMB.g.gain.linearRampToValueAtTime(PAMB.gain,ac.currentTime+1.2);PAMB.g.connect(AUD.fx||ac.destination);PAMB.next=ac.currentTime;
    const sched=()=>{if(!PAMB.on)return;const ac=AUD.ac;while(PAMB.next<ac.currentTime+1.5){const s=ac.createBufferSource();s.buffer=PAMB.buf;s.playbackRate.value=.97+Math.random()*.06;s.connect(PAMB.g);s.start(PAMB.next);PAMB.next+=PAMB.buf.duration-.25;}};
    sched();PAMB.timer=setInterval(()=>{if(!document.getElementById('pdk')){padAmbStop();return;}sched();},400);});}
function padAmbStop(){if(!PAMB.on)return;PAMB.on=false;clearInterval(PAMB.timer);if(PAMB.g&&AUD.ac){const g=PAMB.g,t=AUD.ac.currentTime;g.gain.cancelScheduledValues(t);g.gain.setValueAtTime(g.gain.value,t);g.gain.linearRampToValueAtTime(0,t+1.2);setTimeout(()=>{try{g.disconnect();}catch(e){}},1500);}PAMB.g=null;}
function padAmbDuck(t,dur){if(!PAMB.g)return;const g=PAMB.g.gain;g.cancelScheduledValues(t);g.setValueAtTime(g.value,t);g.linearRampToValueAtTime(0,t+.25);g.setValueAtTime(0,t+dur-.45);g.linearRampToValueAtTime(PAMB.gain,t+dur);}
paddockAnim=(o=>function(){const r=o.apply(this,arguments);padAmbStart();return r;})(paddockAnim);
closeModal=(o=>function(){const r=o.apply(this,arguments);setTimeout(()=>{if(!document.getElementById('pdk'))padAmbStop();},50);return r;})(closeModal);
